let navTriggerButton=document.getElementById("nav_trigger_button"),navContainer=document.getElementById("main-menu-container"),navCloseButton=document.getElementById("nav_close_button");if(navTriggerButton&&navContainer){navContainer.prepend(navCloseButton);let n=function(){navContainer.classList.contains("inactive")?(navTriggerButton.classList.remove("active"),navTriggerButton.classList.add("inactive"),navContainer.classList.remove("inactive"),navContainer.classList.add("active"),navCloseButton.focus()):(navTriggerButton.classList.remove("inactive"),navTriggerButton.classList.add("active"),navContainer.classList.remove("active"),navContainer.classList.add("inactive"),navTriggerButton.focus())};navTriggerButton.addEventListener("click",function(t){n()}),navCloseButton.addEventListener("click",function(t){n()})}